import java.io.*;
import java.util.*;

public class Div375BVariant1 {
    BufferedReader reader;
    PrintWriter writer;
    StringTokenizer tokenizer;

    public static void main(String[] args) throws IOException {
        new Div375BVariant1().execute();
    }

    void execute() throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(System.out);
        process();
        writer.flush();
    }

    void process() throws IOException {
        int length = readInt();
        char[] sequence = readString().toCharArray();
        int maxSegment = 0, nestedCount = 0;
        for (int index = 0; index < length; index++) {
            if (sequence[index] == '(') {
                int tempCount = 0;
                for (int j = index + 1; j < length; j++) {
                    if (sequence[j] == ')') {
                        if (tempCount > 0) nestedCount++;
                        break;
                    }
                    if (sequence[j] == '_') {
                        if (tempCount > 0) {
                            nestedCount++;
                            tempCount = 0;
                        }
                    } else {
                        tempCount++;
                    }
                }
            } else if (sequence[index] == ')' || sequence[index] == '_') {
                int count = 0;
                for (int j = index + 1; j < length && sequence[j] != ')' && sequence[j] != '_' && sequence[j] != '('; j++) {
                    count++;
                }
                maxSegment = Math.max(maxSegment, count);
            } else {
                int count = 0;
                for (int j = index; j < length && sequence[j] != ')' && sequence[j] != '_' && sequence[j] != '('; j++) {
                    count++;
                }
                maxSegment = Math.max(maxSegment, count);
                index += count - 1;
            }
        }
        writer.println(maxSegment + " " + nestedCount);
    }

    String readString() throws IOException {
        return nextToken();
    }

    int readInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    String nextToken() throws IOException {
        if (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }
}
